def merge_intervals(intervals):
    if not intervals:
        return []

    merged = []
    current = intervals[0]

    for interval in intervals[1:]:
        if current[1] >= interval[0]:
            current[1] = max(current[1], interval[1])
        else:
            merged.append(current)
            current = interval

    merged.append(current)

    return sorted(merged, key=lambda x: (x[0], x[1]))
