def subarray_sum(nums, target):
    count = 0
    current_sum = 0
    seen = {0: 1}

    for num in nums:
        current_sum += num
        if current_sum - target in seen:
            count += seen[current_sum - target]
        if current_sum not in seen:
            seen[current_sum] = 0
        seen[current_sum] += 1

    return count
```

